import * as React from "react";
import {
  AreaChart, Area, BarChart, Bar, Cell, PieChart, Pie, RadarChart, Radar, PolarGrid, PolarAngleAxis, RadialBarChart, RadialBar,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as ChartTooltip,
  ResponsiveContainer,
} from "recharts";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { Button } from "./button";
import { Empty } from "./empty";
import { Input } from "./forms";
import { Pagination } from "./navigation";
export function Table({
  columns,
  rows,
  caption,
}: {
  columns: string[];
  rows: React.ReactNode[][];
  caption: string;
}) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-start text-sm">
        <caption className="pb-3 text-start text-muted">{caption}</caption>
        <thead>
          <tr>
            {columns.map((c) => (
              <th
                scope="col"
                key={c}
                className="border-b border-line px-3 py-3 text-start font-medium"
              >
                {c}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={i} className="hover:bg-surface/60">
              {r.map((c, n) => (
                <td key={n} className="border-b border-line px-3 py-3">
                  {c}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
export type DataRow = {
  id: string;
  name: string;
  status: string;
  amount: number;
};
export function DataTable({ rows }: { rows: DataRow[] }) {
  const [query, setQuery] = React.useState(""),
    [sort, setSort] = React.useState(false),
    [page, setPage] = React.useState(1);
  const filtered = rows
    .filter((r) => r.name.toLowerCase().includes(query.toLowerCase()))
    .sort((a, b) => (sort ? b.amount - a.amount : a.amount - b.amount));
  const total = Math.max(1, Math.ceil(filtered.length / 5));
  const current = Math.min(page, total);
  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-3">
        <Input
          aria-label="Filter records"
          placeholder="Filter by name…"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setPage(1);
          }}
          className="max-w-xs"
        />
        <Button
          tone="outline"
          onClick={() => setSort(!sort)}
          aria-pressed={sort}
        >
          Amount {sort ? "descending" : "ascending"}
        </Button>
      </div>
      {filtered.length ? (
        <Table
          caption={filtered.length + " records"}
          columns={["Name", "Status", "Amount"]}
          rows={filtered
            .slice((current - 1) * 5, current * 5)
            .map((r) => [
              r.name,
              r.status,
              new Intl.NumberFormat("en", {
                style: "currency",
                currency: "EUR",
              }).format(r.amount),
            ])}
        />
      ) : (
        <Empty title="No matching records">Try a different name.</Empty>
      )}
      <Pagination page={current} total={total} onChange={setPage} />
    </div>
  );
}
export type ChartKind = 'area'|'bar'|'line'|'pie'|'radar'|'radial';
export function Chart({data,label,kind='line',compact=false}:{data:{name:string;value:number}[];label:string;kind?:ChartKind;compact?:boolean}){
const tooltip=<ChartTooltip cursor={false} contentStyle={{background:'var(--color-card)',border:'1px solid var(--color-line)',color:'var(--color-ink)',borderRadius:10,fontSize:12,boxShadow:'0 8px 24px #0000000d'}}/>;
const colors=['var(--color-terracotta)','var(--color-gold)','var(--color-chart-3)','var(--color-chart-4)','var(--color-chart-5)'];
const axes=<><CartesianGrid stroke="var(--color-line)" vertical={false} strokeDasharray="3 4"/><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fill:'var(--color-muted)',fontSize:10}} dy={8}/>{!compact&&<YAxis width={30} tickLine={false} axisLine={false} tick={{fill:'var(--color-muted)',fontSize:10}}/>}</>;
let drawing:React.ReactElement;
if(kind==='pie')drawing=<PieChart accessibilityLayer>{tooltip}<Pie data={data} dataKey="value" nameKey="name" innerRadius="52%" outerRadius="80%" paddingAngle={4} cornerRadius={5} isAnimationActive={false}>{data.map((d,i)=><Cell key={d.name} fill={colors[i%colors.length]} stroke="none"/>)}</Pie></PieChart>;
else if(kind==='radar')drawing=<RadarChart data={data} accessibilityLayer><PolarGrid stroke="var(--color-line)"/><PolarAngleAxis dataKey="name" tick={{fill:'var(--color-muted)',fontSize:11}}/>{tooltip}<Radar dataKey="value" stroke={colors[0]} fill={colors[0]} fillOpacity={.15} isAnimationActive={false}/></RadarChart>;
else if(kind==='radial')drawing=<RadialBarChart data={data.map((d,i)=>({...d,fill:colors[i%colors.length]}))} innerRadius="25%" outerRadius="95%" startAngle={90} endAngle={-270} accessibilityLayer>{tooltip}<RadialBar dataKey="value" background={{fill:'var(--color-surface)'}} cornerRadius={8} isAnimationActive={false}/></RadialBarChart>;
else if(kind==='bar')drawing=<BarChart data={data} accessibilityLayer margin={{top:12,right:4,bottom:5,left:0}}>{axes}{tooltip}<Bar dataKey="value" fill={colors[0]} radius={[5,5,2,2]} maxBarSize={38} isAnimationActive={false}>{data.map((d,i)=><Cell key={d.name} fill={i===data.length-1?colors[0]:'var(--color-chart-3)'}/>)}</Bar></BarChart>;
else if(kind==='area')drawing=<AreaChart data={data} accessibilityLayer margin={{top:12,right:4,bottom:5,left:0}}>{axes}{tooltip}<Area dataKey="value" type="monotone" fill={colors[0]} fillOpacity={.13} stroke={colors[0]} strokeWidth={2} isAnimationActive={false}/></AreaChart>;
else drawing=<LineChart data={data} accessibilityLayer margin={{top:12,right:4,bottom:5,left:0}}>{axes}{tooltip}<Line dataKey="value" type="monotone" stroke={colors[0]} strokeWidth={2} dot={false} activeDot={{r:4,strokeWidth:3,stroke:'var(--color-card)'}} isAnimationActive={false}/></LineChart>;
return <figure><figcaption className={compact?'sr-only':'mb-4 text-sm font-medium'}>{label}</figcaption>{data.length?<><div className={compact?'h-40 min-w-0':'h-60 min-w-0'}><ResponsiveContainer width="100%" height="100%" minWidth={0}>{drawing}</ResponsiveContainer></div><details className={compact?'mt-3 text-[10px] text-muted':'mt-4 text-xs text-muted'}><summary>View data</summary><Table caption={label} columns={['Period','Value']} rows={data.map(d=>[d.name,d.value])}/></details></>:<Empty title="No chart data"/>}</figure>
}
export function Carousel({
  slides,
}: {
  slides: { title: string; description: string }[];
}) {
  const [index, setIndex] = React.useState(0);
  if (!slides.length) return <Empty title="No slides" />;
  const current = Math.min(index, slides.length - 1);
  return (
    <section aria-roledescription="carousel" aria-label="Highlights">
      <div
        role="group"
        aria-roledescription="slide"
        aria-label={current + 1 + " of " + slides.length}
        className="rounded-xl bg-surface p-8"
      >
        <h3 className="font-editorial text-2xl">{slides[current].title}</h3>
        <p className="mt-3 text-sm text-muted">{slides[current].description}</p>
      </div>
      <div className="mt-4 flex items-center justify-between">
        <Button
          tone="outline"
          aria-label="Previous slide"
          disabled={current === 0}
          onClick={() => setIndex(current - 1)}
        >
          <ChevronLeft className="size-4" />
        </Button>
        <span aria-live="polite" className="text-xs">
          {current + 1} / {slides.length}
        </span>
        <Button
          tone="outline"
          aria-label="Next slide"
          disabled={current === slides.length - 1}
          onClick={() => setIndex(current + 1)}
        >
          <ChevronRight className="size-4" />
        </Button>
      </div>
    </section>
  );
}
export function Resizable({
  left,
  right,
}: {
  left: React.ReactNode;
  right: React.ReactNode;
}) {
  const [width, setWidth] = React.useState(40);
  return (
    <div>
      <label className="mb-3 block text-xs">
        Left panel width
        <input
          aria-label="Left panel width"
          className="ms-3 accent-terracotta"
          type="range"
          min="20"
          max="70"
          value={width}
          onChange={(e) => setWidth(Number(e.target.value))}
        />
      </label>
      <div className="flex min-h-36 overflow-hidden rounded-xl border border-line">
        <div
          style={{ width: width + "%" }}
          className="overflow-auto border-e border-line p-4"
        >
          {left}
        </div>
        <div className="min-w-0 flex-1 overflow-auto p-4">{right}</div>
      </div>
    </div>
  );
}

import * as React from "react";
import { LoaderCircle } from "lucide-react";
import { cx } from "./utils";

export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  tone?: "primary" | "secondary" | "outline" | "quiet" | "danger" | "accent";
  size?: "sm" | "md" | "lg";
  loading?: boolean;
};

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      tone = "primary",
      size = "md",
      loading = false,
      disabled,
      children,
      className,
      type = "button",
      ...props
    },
    ref,
  ) {
    return (
      <button
        {...props}
        ref={ref}
        type={type}
        disabled={disabled || loading}
        aria-busy={loading ? true : props["aria-busy"]}
        className={cx(
          "a-button relative",
          {
            "bg-ink text-paper hover:bg-ink/85": tone === "primary",
            "bg-surface text-ink hover:bg-surface/70": tone === "secondary",
            "border border-control bg-transparent text-ink": tone === "outline",
            "bg-transparent text-ink hover:bg-surface": tone === "quiet",
            "bg-danger text-on-danger": tone === "danger",
            "bg-gold text-[#181818]": tone === "accent",
          },
          {
            "min-h-11 sm:min-h-9 px-3 py-2 text-xs": size === "sm",
            "min-h-11 px-4 py-2 text-sm": size === "md",
            "min-h-13 px-6 py-3 text-base": size === "lg",
          },
          loading && "disabled:opacity-100",
          className,
        )}
      >
        <span
          className="inline-flex min-w-0 items-center justify-center gap-2 [&_svg]:shrink-0"
          style={{ opacity: loading ? 0 : undefined }}
        >
          {children}
        </span>
        {loading && (
          <span
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 flex items-center justify-center"
          >
            <LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" />
          </span>
        )}
      </button>
    );
  },
);

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export const cx = (...values: ClassValue[]) => twMerge(clsx(values));

import * as React from "react";

export function Empty({
  title,
  children,
  action,
}: {
  title: string;
  children?: React.ReactNode;
  action?: React.ReactNode;
}) {
  return (
    <div className="rounded-xl border border-dashed border-line p-10 text-center">
      <h3 className="font-editorial text-2xl">{title}</h3>
      <div className="mx-auto my-4 max-w-sm text-sm text-muted">{children}</div>
      {action}
    </div>
  );
}

import * as React from "react";
import {
  Checkbox as RC,
  Switch as RS,
  Slider as SL,
  Select as SE,
  RadioGroup as RG,
  Toggle as TO,
  ToggleGroup as TG,
} from "radix-ui";
import { Check, ChevronDown } from "lucide-react";
import { DayPicker } from "react-day-picker";
import { cx } from "./utils";
export const Input = React.forwardRef<
  HTMLInputElement,
  React.InputHTMLAttributes<HTMLInputElement>
>(function Input({ className, ...p }, ref) {
  return <input ref={ref} className={cx("a-input", className)} {...p} />;
});
export const Textarea = React.forwardRef<
  HTMLTextAreaElement,
  React.TextareaHTMLAttributes<HTMLTextAreaElement>
>(function Textarea({ className, ...p }, ref) {
  return (
    <textarea
      ref={ref}
      rows={4}
      className={cx("a-input resize-y", className)}
      {...p}
    />
  );
});
export function Label(p: React.LabelHTMLAttributes<HTMLLabelElement>) {
  return <label {...p} className={cx("text-sm font-medium", p.className)} />;
}
export function Field({
  label,
  hint,
  error,
  children,
}: {
  label: string;
  hint?: string;
  error?: string;
  children: React.ReactElement;
}) {
  const id = React.useId();
  const description =
    [hint ? id + "-hint" : "", error ? id + "-error" : ""]
      .filter(Boolean)
      .join(" ") || undefined;
  return (
    <div className="grid gap-2">
      <Label htmlFor={id}>{label}</Label>
      {React.cloneElement(
        children as React.ReactElement<React.HTMLAttributes<HTMLElement>>,
        {
          id,
          "aria-describedby": description,
          "aria-invalid": error ? true : undefined,
        },
      )}
      {hint && (
        <p id={id + "-hint"} className="text-xs text-muted">
          {hint}
        </p>
      )}
      {error && (
        <p role="alert" id={id + "-error"} className="text-xs text-danger">
          {error}
        </p>
      )}
    </div>
  );
}
export function InputGroup({
  prefix,
  suffix,
  children,
}: {
  prefix?: React.ReactNode;
  suffix?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div className="flex items-center gap-2 rounded-lg border border-line bg-card px-3 [&_input]:border-0 [&_input]:bg-transparent">
      <span className="text-sm text-muted">{prefix}</span>
      {children}
      <span className="text-sm text-muted">{suffix}</span>
    </div>
  );
}
export function Checkbox({
  label,
  ...props
}: React.ComponentProps<typeof RC.Root> & { label: string }) {
  const generatedId = React.useId();
  const id = props.id ?? generatedId;
  return (
    <div className="flex items-center gap-3">
      <RC.Root
        id={id}
        {...props}
        className="flex size-5 shrink-0 items-center justify-center rounded border border-line bg-card data-[state=checked]:border-ink data-[state=checked]:bg-ink data-[state=checked]:text-paper disabled:opacity-40"
      >
        <RC.Indicator>
          <Check className="size-3.5" />
        </RC.Indicator>
      </RC.Root>
      <label htmlFor={id} className="text-sm">
        {label}
      </label>
    </div>
  );
}
export function Switch({
  label,
  className,
  ...props
}: React.ComponentProps<typeof RS.Root> & { label: string }) {
  const generatedId = React.useId();
  const id = props.id ?? generatedId;
  return (
    <div className="flex min-h-11 items-center gap-3">
      <RS.Root
        id={id}
        {...props}
        className={cx(
          "relative w-10 shrink-0 rounded-full border border-line bg-surface p-0.5 data-[state=checked]:bg-terracotta disabled:opacity-40",
          className,
        )}
      >
        <RS.Thumb className="relative start-0 block size-4 rounded-full bg-card transition-[inset-inline-start] data-[state=checked]:start-[calc(100%-16px)] motion-reduce:transition-none" />
      </RS.Root>
      <label htmlFor={id} className="text-sm">
        {label}
      </label>
    </div>
  );
}
export function RadioGroup({
  label,
  options,
  ...props
}: React.ComponentProps<typeof RG.Root> & {
  label: string;
  options: { value: string; label: string; disabled?: boolean }[];
}) {
  const uid = React.useId();
  return (
    <RG.Root aria-label={label} {...props} className="grid gap-3">
      {options.map((o, i) => (
        <div className="flex items-center gap-3" key={o.value}>
          <RG.Item
            id={uid + i}
            value={o.value}
            disabled={o.disabled}
            className="flex size-5 items-center justify-center rounded-full border border-line disabled:opacity-40"
          >
            <RG.Indicator className="size-2.5 rounded-full bg-terracotta" />
          </RG.Item>
          <Label htmlFor={uid + i}>{o.label}</Label>
        </div>
      ))}
    </RG.Root>
  );
}
export function NativeSelect({
  options,
  ...props
}: React.SelectHTMLAttributes<HTMLSelectElement> & {
  options: { value: string; label: string; disabled?: boolean }[];
}) {
  return (
    <select {...props} className={cx("a-input", props.className)}>
      {options.map((o) => (
        <option key={o.value} {...o}>
          {o.label}
        </option>
      ))}
    </select>
  );
}
export function Select({
  label,
  options,
  placeholder = "Choose an option",
  id,
  "aria-invalid": invalid,
  "aria-describedby": describedBy,
  ...props
}: React.ComponentProps<typeof SE.Root> & {
  id?: string;
  "aria-invalid"?: React.AriaAttributes["aria-invalid"];
  "aria-describedby"?: string;
  label: string;
  placeholder?: string;
  options: {
    value: string;
    label: string;
    disabled?: boolean;
    description?: string;
    swatch?: string;
  }[];
}) {
  return (
    <SE.Root {...props}>
      <SE.Trigger
        id={id}
        aria-invalid={invalid}
        aria-describedby={describedBy}
        aria-label={label}
        className="a-input flex items-center justify-between gap-3 text-start data-[state=open]:border-terracotta [&>span:first-child]:min-w-0 [&>span:first-child]:truncate"
      >
        <SE.Value placeholder={placeholder} />
        <SE.Icon>
          <ChevronDown className="size-4 shrink-0 text-muted" />
        </SE.Icon>
      </SE.Trigger>
      <SE.Portal>
        <SE.Content
          className="a-popup w-[var(--radix-select-trigger-width)] max-w-[calc(100vw-24px)] overflow-hidden"
          position="popper"
          sideOffset={6}
          collisionPadding={12}
        >
          <SE.Viewport className="max-h-[min(320px,var(--radix-select-content-available-height))] p-1">
            {options.map((o) => (
              <SE.Item
                key={o.value}
                value={o.value}
                disabled={o.disabled}
                textValue={o.label}
                className="relative flex min-h-11 cursor-default items-center gap-3 rounded-md px-3 py-2.5 text-sm outline-none data-[state=checked]:bg-surface data-[highlighted]:ring-1 data-[highlighted]:ring-inset data-[highlighted]:ring-terracotta data-[disabled]:pointer-events-none data-[disabled]:opacity-40"
              >
                {o.swatch && (
                  <span
                    aria-hidden="true"
                    className="size-5 shrink-0 rounded-full border border-line"
                    style={{ backgroundColor: o.swatch }}
                  />
                )}
                <span className="min-w-0 flex-1 break-words">
                  <SE.ItemText>{o.label}</SE.ItemText>
                  {o.description && (
                    <span className="mt-0.5 block text-xs leading-relaxed text-muted">
                      {o.description}
                    </span>
                  )}
                </span>
                <span className="flex size-4 shrink-0 items-center justify-center">
                  <SE.ItemIndicator>
                    <Check className="size-4" />
                  </SE.ItemIndicator>
                </span>
              </SE.Item>
            ))}
          </SE.Viewport>
        </SE.Content>
      </SE.Portal>
    </SE.Root>
  );
}
export function Slider({
  label,
  ...props
}: React.ComponentProps<typeof SL.Root> & { label: string }) {
  const values = props.value || props.defaultValue || [50];
  return (
    <SL.Root
      {...props}
      defaultValue={props.defaultValue || (!props.value ? [50] : undefined)}
      className="relative flex h-8 w-full touch-none items-center"
    >
      <SL.Track className="relative h-1.5 grow rounded-full bg-surface">
        <SL.Range className="absolute h-full rounded-full bg-terracotta" />
      </SL.Track>
      {values.map((_, i) => (
        <SL.Thumb
          key={i}
          aria-label={values.length > 1 ? label + " " + (i + 1) : label}
          className="block size-5 rounded-full border border-line bg-card shadow-sm"
        />
      ))}
    </SL.Root>
  );
}
export function Toggle({
  children,
  ...props
}: React.ComponentProps<typeof TO.Root>) {
  return (
    <TO.Root
      {...props}
      className="a-button min-h-10 border border-line px-3 text-sm data-[state=on]:bg-ink data-[state=on]:text-paper"
    >
      {children}
    </TO.Root>
  );
}
export function ToggleGroup({
  label,
  options,
  value,
  onValueChange,
}: {
  label: string;
  options: string[];
  value?: string;
  onValueChange?: (v: string) => void;
}) {
  return (
    <TG.Root
      type="single"
      aria-label={label}
      value={value}
      onValueChange={onValueChange}
      className="inline-flex gap-1 rounded-lg bg-surface p-1"
    >
      {options.map((o) => (
        <TG.Item
          key={o}
          value={o}
          className="rounded-md px-3 py-2 text-sm data-[state=on]:bg-card"
        >
          {o}
        </TG.Item>
      ))}
    </TG.Root>
  );
}
export function Calendar(props: React.ComponentProps<typeof DayPicker>) {
  return <DayPicker {...props} className="a-calendar" showOutsideDays />;
}
export function DatePicker(
  props: Omit<React.InputHTMLAttributes<HTMLInputElement>, "type">,
) {
  return <Input {...props} type="date" />;
}
export function Combobox({
  label,
  options,
  ...props
}: React.InputHTMLAttributes<HTMLInputElement> & {
  label: string;
  options: string[];
}) {
  const id = React.useId();
  return (
    <>
      <Input {...props} aria-label={label} list={id} />
      <datalist id={id}>
        {options.map((o) => (
          <option key={o} value={o} />
        ))}
      </datalist>
    </>
  );
}
export function InputOTP({
  length = 6,
  label = "Verification code",
  value,
  onChange,
  disabled,
}: {
  length?: number;
  label?: string;
  value: string;
  onChange: (v: string) => void;
  disabled?: boolean;
}) {
  return (
    <Input
      aria-label={label}
      inputMode="numeric"
      autoComplete="one-time-code"
      value={value}
      disabled={disabled}
      maxLength={length}
      pattern={"[0-9]{" + length + "}"}
      onChange={(e) =>
        onChange(e.target.value.replace(/\D/g, "").slice(0, length))
      }
      className="max-w-64 text-center font-mono text-xl tracking-[0.5em]"
    />
  );
}

import * as React from "react";
import {
  Tabs as TB,
  Accordion as AC,
  Collapsible as CO,
  DropdownMenu as DM,
  ContextMenu as CM,
  Menubar as MB,
  NavigationMenu as NM,
  ScrollArea as SA,
} from "radix-ui";
import { Search, Menu, ChevronRight } from "lucide-react";
import { Button } from "./button";
import { Modal } from "./overlays";
export function Tabs({
  items,
  defaultValue,
}: {
  items: { value: string; label: string; content: React.ReactNode }[];
  defaultValue?: string;
}) {
  return (
    <TB.Root defaultValue={defaultValue || items[0]?.value}>
      <TB.List
        aria-label="Sections"
        className="mb-5 flex flex-wrap gap-1 rounded-lg bg-surface p-1"
      >
        {items.map((i) => (
          <TB.Trigger
            key={i.value}
            value={i.value}
            className="rounded-md px-4 py-2 text-sm data-[state=active]:bg-card"
          >
            {i.label}
          </TB.Trigger>
